using phosphor::dump::ramoops::Manager;

namespace
{

using CreateParameters =
    sdbusplus::common::xyz::openbmc_project::dump::Create::CreateParameters;
using DumpType =
    sdbusplus::common::xyz::openbmc_project::dump::Create::DumpType;
