TEST(NsmDeviceUtils, PreservesBoardQualifiedLeaf)
{
    EXPECT_EQ(deviceSelectorFromPath(
                  "/xyz/openbmc_project/inventory/system/chassis/"
                  "Bay_C_CX_0/NetworkAdapters/Bay_C_CX_NIC_0"),
              "Bay_C_CX_NIC_0");
